//! Plain Rust `pub` and C-ABI exports contrasted with the wasm bridge.
//!
//! The bridge surface is generated by `#[wasm_bindgen]` and its glue is distinct
//! from normal Rust visibility (`pub`) and from `extern "C"` / `#[unsafe(no_mangle)]`.

/// Ordinary Rust visibility — visible to Rust consumers, not to JS/Wasm imports.
///
/// This is `pub` in the Rust sense. It does not create a foreign export and
/// does not generate wasm-bindgen glue or JS bindings.
pub fn rust_public_add(a: i32, b: i32) -> i32 {
    a + b
}

/// Marker consumed by `fixture_overview` to keep this module linked.
pub fn rust_visibility_anchor() -> &'static str {
    let _ = rust_public_add(1, 2);
    "rust-pub"
}

/// Plain C ABI export — a stable `extern "C"` symbol with `no_mangle`.
///
/// This reaches the linker as `c_exported_add` via the C ABI, not via the
/// wasm-bindgen section machinery. Foreign consumers link by symbol name and
/// use `extern "C"` declarations; strings and slices are not ABI-adapted.
#[unsafe(no_mangle)]
pub extern "C" fn c_exported_add(a: i32, b: i32) -> i32 {
    a + b
}

/// Plain C exported value for completeness.
#[unsafe(no_mangle)]
pub static C_EXPORTED_VALUE: i32 = 0x1a2b;

/// Convenience wrapper describing the contrast.
pub fn plain_export_label() -> &'static str {
    // Call both to keep them observed for graph purposes.
    let _ = rust_public_add(2, 3);
    let _ = c_exported_add(2, 3);
    let _ = C_EXPORTED_VALUE;
    "plain-exports"
}
